void vin_reset(void)
{
  static Vin_Info cur_info ;
  
  nvfs_wr_delete(nvfs_vin, &cur_info.vin.code , sizeof(cur_info.vin.code)) ;

  #if DBG_VIN == 1
    dbg_tx_text ("\nVin Reset") ;
  #endif 
}


